<script src="./template/bootstrap.min.js"></script>
<script>
    (function () {
        var buttons = document.querySelectorAll('[data-tab]');
        var panels = document.querySelectorAll('[data-panel]');
        function activate(name) {
            var all = name === 'todos';
            panels.forEach(function (panel) {
                panel.classList.toggle('active', all || panel.getAttribute('data-panel') === name);
            });
            buttons.forEach(function (button) {
                button.classList.toggle('active', button.getAttribute('data-tab') === name);
            });
        }
        buttons.forEach(function (button) {
            button.addEventListener('click', function () {
                activate(button.getAttribute('data-tab'));
            });
        });
    })();
</script>
